using System;using System.IO;using System.Threading;using System.Web.Script.Serialization;using System.Collections.Generic;using System.Linq;
class ProtectionAcceptance {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static Dictionary<string,object> Read(NativeProtectionCoordinator c){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(c.Snapshot()));}
 static Dictionary<string,object> Scan(NativeProtectionCoordinator c){return (Dictionary<string,object>)Read(c)["scan"];}
 static void Wait(Func<bool> condition,int seconds,string message){for(int i=0;i<seconds*4;i++){if(condition())return;Thread.Sleep(250);}throw new Exception(message);}
 static int Main(){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qualification-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string downloads=Path.Combine(root,"Downloads");Directory.CreateDirectory(downloads);string vault=Path.Combine(root,"Vault");object original;using(var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey("Software\\Sentinel\\Protection")){original=key.GetValue("DownloadMonitoring");}
 try{using(var c=new NativeProtectionCoordinator(null,downloads,vault)){
  Wait(()=>Convert.ToBoolean(Read(c)["available"]),300,"Pinned signature runtime unavailable: "+Json.Serialize(Read(c)));Console.WriteLine("Real pinned engine ready: "+Read(c)["signatures"]+" signatures");c.SetMonitoring(true);
  string partial=Path.Combine(downloads,"arrival.txt.crdownload");File.WriteAllText(partial,"Ordinary harmless completed download acceptance.");Thread.Sleep(5000);if(Json.Serialize(Read(c)).Contains("Download checked"))throw new Exception("Partial download inspected");File.Move(partial,Path.Combine(downloads,"arrival.txt"));
  Wait(()=>Json.Serialize(Read(c)).Contains("Download checked"),60,"Completed download not checked");Console.WriteLine("Actual watcher -> rename -> stable bytes -> official engine -> activity PASS");
  c.ScanSelected(downloads);Wait(()=>new[]{"completed","incomplete"}.Contains((string)Scan(c)["state"]),30,"Selected folder did not finish");if(Convert.ToInt64(Scan(c)["checkedFiles"])!=1)throw new Exception("Selected file count incorrect");Console.WriteLine("Selected folder scan PASS");
  string large=Path.Combine(root,"large-harmless.dat");using(var file=new FileStream(large,FileMode.CreateNew,FileAccess.Write)){file.SetLength(300L*1024*1024);}c.ScanSelected(large);Wait(()=>new[]{"completed","incomplete"}.Contains((string)Scan(c)["state"]),180,"Large signature scan did not finish");if((string)Scan(c)["state"]!="completed"||Convert.ToInt64(Scan(c)["bytesChecked"])!=300L*1024*1024||Convert.ToInt64(Scan(c)["checkedFiles"])!=1)throw new Exception("Large native scan incomplete: "+Json.Serialize(Read(c)));Console.WriteLine("Actual 300 MiB official signature scan and full-file hash PASS");using(var file=new FileStream(large,FileMode.Open,FileAccess.Write)){file.Position=file.Length-1;file.WriteByte(65);}c.ScanSelected(large);Thread.Sleep(2000);c.Cancel();Wait(()=>(string)Scan(c)["state"]=="cancelled",150,"In-flight large scan cooperative cancellation exceeded its 120-second native scan budget plus cleanup allowance");Wait(()=>Convert.ToBoolean(Read(c)["available"]),120,"Scanner did not recover after large cancellation");Console.WriteLine("In-flight large scan cooperative cancellation and continued worker availability PASS");File.Delete(large);
  c.Scan("quick");Wait(()=>new[]{"completed","incomplete"}.Contains((string)Scan(c)["state"]),30,"Quick scan did not finish");Console.WriteLine("Quick scan PASS");
  string bulk=Path.Combine(root,"bulk");Directory.CreateDirectory(bulk);for(int i=0;i<1000;i++)File.WriteAllText(Path.Combine(bulk,i+".txt"),"Ordinary harmless scheduling content "+i);c.ScanSelected(bulk);File.WriteAllText(Path.Combine(downloads,"during-scan.txt"),"Harmless content arriving during a scan.");Wait(()=>Json.Serialize(Read(c)).Split(new[]{"Download checked"},StringSplitOptions.None).Length>=3,40,"New download did not interrupt manual traversal");if(!new[]{"scanning","paused"}.Contains((string)Scan(c)["state"]))throw new Exception("Manual scan finished before priority could be verified");Console.WriteLine("Download priority during manual traversal PASS");c.Cancel();Wait(()=> (string)Scan(c)["state"]=="cancelled",30,"Cancellation not acknowledged");Wait(()=>Json.Serialize(Read(c)).Contains("during-scan.txt")||Convert.ToInt32(Read(c)["queue"])==0,40,"Automatic queue stalled");Console.WriteLine("Manual cancellation and independent automatic queue PASS");
  c.Scan("full");Thread.Sleep(3000);c.Cancel();Wait(()=> (string)Scan(c)["state"]=="cancelled",30,"Full scan Stop not acknowledged");Console.WriteLine("Actual Full Scan start / progress / Stop PASS (entire-drive completion not claimed)");
  c.SetMonitoring(false);if(Convert.ToBoolean(Read(c)["monitoring"]))throw new Exception("Monitoring remained enabled");Console.WriteLine("Monitoring switch PASS");Console.WriteLine(Json.Serialize(Read(c)));
 }}finally{using(var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey("Software\\Sentinel\\Protection")){if(original==null)key.DeleteValue("DownloadMonitoring",false);else key.SetValue("DownloadMonitoring",original);}if(Directory.Exists(root))Directory.Delete(root,true);}return 0;
 }
}
